"""Return sorted list of prime factors of n, for n <= 120"""
def get_factors(n: Any) -> object {
    assert (1 <= n < 121) , "Number too large";
    return [
        i
        for i in range(1, (n + 1))
        if ((n % i) == 0)
    ];
}

